# RULER data per context length, pinned to an exact dataset commit so everyone scores the same examples.
# 4K-16K: the kvpress RULER set. 32K-128K: generated by data/generate_ruler.sh with the same settings.
RULER_SHORT = ("simonjegou/ruler", "24adceac8a0e6532936e8d721cd9e9084d2e4686")
RULER_LONG = ("Jhc6880/ruler-long", "deda02ec4c98e4cd6197f4738b03a1070767abf1")
